<script setup>
import { computed, ref, watch } from 'vue';
import { Link, router, useForm } from '@inertiajs/vue3';
import { ElMessage } from 'element-plus';
import AdminLayout from '../../../Layouts/AdminLayout.vue';

const props=defineProps({article:Object,selectedWords:Array,coverUrl:String,detailImageUrl:String,kind:{type:String,default:'article'},series:Object,nextChapterNo:{type:Number,default:1},nextSortOrder:{type:Number,default:1},readingLevels:{type:Array,default:()=>[]}});
const editing=computed(()=>!!props.article);
const isChapter=computed(()=>props.kind==='chapter');
const itemBase=computed(()=>isChapter.value?`/admin/chapters/${props.article?.id}`:`/admin/articles/${props.article?.id}`);
const editorTitle=computed(()=>isChapter.value?(editing.value?'编辑章节':'新建章节'):(editing.value?'编辑文章':'新建文章'));
const initialParagraphs=(props.article?.body||[{sentences:[''],translation:''}]).map(p=>({sentences:(p.sentences||[]).join('\n'),translation:(p.sentenceTranslations||[]).some(line=>String(line||'').trim())?(p.sentenceTranslations||[]).join('\n'):(p.translation||''),sentenceTranslations:p.sentenceTranslations||[]}));
const articleForm=useForm({title:props.article?.title||'',translation:props.article?.translation||'',level:props.article?.level||props.series?.level||'',minutes:props.article?.minutes||'',slug:props.article?.slug||'',chapterNo:props.article?.chapter_no||props.nextChapterNo,sortOrder:props.article?.sort_order??props.nextSortOrder,rightsType:props.article?.rights_type||'',rightsNote:props.article?.rights_note||'',paragraphs:initialParagraphs,coverImage:null,detailImage:null});
const analysis=props.article?.analysis||{};
const analysisForm=useForm({type:analysis.type||'richtext',format:analysis.format||'html',html:analysis.html||'',url:analysis.url||'',title:analysis.title||'',summary:analysis.summary||''});
const selected=ref((props.selectedWords||[]).map(w=>({...w,id:Number(w.id)})));
const search=ref('');const results=ref([]);const searching=ref(false);let timer;
const wordForm=useForm({wordIds:selected.value.map(w=>w.id)});
const questionForm=useForm({questions:(props.article?.questions||[]).map((q,i)=>({uiKey:`question-${q.id||i}`,id:q.id,questionType:q.question_type||'细节理解',kind:q.kind||'choice',prompt:q.prompt||'',promptCn:q.prompt_cn||'',options:(q.options||[]).join('\n'),answer:q.kind==='choice'?String.fromCharCode(65+(Number(q.answer)||0)):(q.answer||''),explanation:q.explanation||''}))});
const expandedParagraphs=ref(initialParagraphs.map((_,i)=>String(i)));
const expandedQuestions=ref(questionForm.questions.map(q=>q.uiKey));
let questionKeySequence=questionForm.questions.length;
const analysisEditor=ref(null);const coverPreview=ref(props.coverUrl||'');const detailPreview=ref(props.detailImageUrl||'');
const quick=ref({open:false,busy:false,error:'',headword:'',ipa:'',senses:[{partOfSpeech:'',meaning:''}]});
const saveAllBusy=ref(false);const saveAllStep=ref('');
const letters='ABCDEFGH';
watch(search,value=>{clearTimeout(timer);if(!value.trim()){results.value=[];return}timer=setTimeout(async()=>{searching.value=true;try{const res=await fetch(`${itemBase.value}/word-options?q=${encodeURIComponent(value)}`,{credentials:'same-origin',headers:{Accept:'application/json'}});const data=await res.json();results.value=res.ok?(data.items||[]):[]}finally{searching.value=false}},250)});
function submitForm(form,method,url,options={}){return new Promise((resolve,reject)=>{let settled=false;form.submit(method,url,{...options,onSuccess:page=>{settled=true;resolve(page)},onError:errors=>{settled=true;reject(new Error(Object.values(errors||{}).flat()[0]||'请检查表单内容'))},onFinish:()=>{if(!settled)reject(new Error('请求未能完成，请检查网络后重试'))}})})}
function withSaveError(request,label){return saveAllBusy.value?request:request.catch(error=>{ElMessage.error(`${label}保存失败：${error.message}`);return null})}
function saveArticle(){articleForm.transform(data=>{const payload={...data,paragraphs:data.paragraphs.map(p=>{const sentences=(Array.isArray(p.sentences)?p.sentences.join('\n'):p.sentences).split(/\r?\n/).map(line=>line.trim()).filter(Boolean);const translationLines=(p.translation||'').split(/\r?\n/).map(line=>line.trim());const aligned=translationLines.length===sentences.length;const sentenceTranslations=aligned?translationLines:(p.sentenceTranslations||[]).length===sentences.length?p.sentenceTranslations:sentences.map(()=> '');return {...p,sentences:sentences.join('\n'),translation:translationLines.filter(Boolean).join(''),sentenceTranslations}})};if(!isChapter.value)delete payload.chapterNo;return payload});return withSaveError(submitForm(articleForm,editing.value?'put':'post',isChapter.value?(editing.value?`/admin/series/${props.series.id}/chapters/${props.article.id}`:`/admin/series/${props.series.id}/chapters`):(editing.value?`/admin/articles/${props.article.id}`:'/admin/articles'),{forceFormData:true}),isChapter.value?'章节':'文章')}
function saveAnalysis(base=itemBase.value){return withSaveError(submitForm(analysisForm,'put',`${base}/analysis`),'语法解析')}
function syncWords(base=itemBase.value){wordForm.wordIds=selected.value.map(w=>w.id);return withSaveError(submitForm(wordForm,'put',`${base}/words`),'重点词汇')}
function saveQuestions(base=itemBase.value){questionForm.transform(data=>({questions:data.questions.map(({uiKey,...question})=>question)}));return withSaveError(submitForm(questionForm,'put',`${base}/questions`),'阅读理解题')}
async function saveAll(){if(saveAllBusy.value)return;saveAllBusy.value=true;saveAllStep.value='保存正文';try{const page=await saveArticle();const savedId=page?.props?.article?.id||props.article?.id;if(!savedId)throw new Error('正文已提交，但未能获取文章编号，请刷新后重试');const base=isChapter.value?`/admin/chapters/${savedId}`:`/admin/articles/${savedId}`;const hasAnalysis=analysisForm.type==='richtext'?Boolean(analysisForm.html.trim()):Boolean(analysisForm.url.trim());if(hasAnalysis){saveAllStep.value='保存语法解析';await saveAnalysis(base)}saveAllStep.value='保存重点词汇';await syncWords(base);saveAllStep.value='保存阅读理解题';await saveQuestions(base);ElMessage.success('文章、解析、重点词汇和阅读理解题已全部保存')}catch(error){ElMessage.error(`保存未完成：${error.message}`)}finally{saveAllBusy.value=false;saveAllStep.value=''}}
function addParagraph(){const index=articleForm.paragraphs.length;articleForm.paragraphs.push({sentences:'',translation:'',sentenceTranslations:[]});expandedParagraphs.value=[String(index)]}
function removeParagraph(index){articleForm.paragraphs.splice(index,1);expandedParagraphs.value=expandedParagraphs.value.filter(name=>Number(name)!==index).map(name=>Number(name)>index?String(Number(name)-1):name)}
function addQuestion(){const uiKey=`new-question-${questionKeySequence++}`;questionForm.questions.push({uiKey,id:null,questionType:'细节理解',kind:'choice',prompt:'',promptCn:'',options:'',answer:'A',explanation:''});expandedQuestions.value=[uiKey]}
function removeQuestion(index){const key=questionForm.questions[index]?.uiKey;questionForm.questions.splice(index,1);expandedQuestions.value=expandedQuestions.value.filter(name=>name!==key)}
function questionOptions(q){return q.options.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}
function paragraphSentenceCount(p){return p.sentences.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).length}
function paragraphSentences(p){return p.sentences.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}
function translationLineCount(p){return p.translation.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).length}
function updateParagraphSentences(p,value){const translations=[...(p.sentenceTranslations||[])];p.sentences=value;const next=paragraphSentences(p);p.sentenceTranslations=next.map((_,index)=>translations[index]||'');}
function paragraphPreview(p){const first=p.sentences.split(/\r?\n/).map(s=>s.trim()).find(Boolean);return first||p.translation||'尚未填写内容'}
function questionPreview(q){return q.prompt.trim()||'尚未填写题干'}
function addWord(w){if(!selected.value.some(x=>Number(x.id)===Number(w.id)))selected.value.push({...w,id:Number(w.id)});}
function removeWord(id){selected.value=selected.value.filter(w=>Number(w.id)!==Number(id))}
function addQuickSense(){quick.value.senses.push({partOfSpeech:'',meaning:''})}
function removeQuickSense(index){if(quick.value.senses.length>1)quick.value.senses.splice(index,1)}
async function quickCreate(){const headword=quick.value.headword.trim();if(!headword)return;quick.value.error='';quick.value.busy=true;try{const senses=quick.value.senses.map(sense=>({partOfSpeech:sense.partOfSpeech.trim(),meaning:sense.meaning.trim()}));const response=await fetch(`${itemBase.value}/words/new`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({headword,senses,ipa:quick.value.ipa})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat().join(' ')||'创建失败');addWord(data);quick.value.open=false;quick.value.headword='';quick.value.ipa='';quick.value.senses=[{partOfSpeech:'',meaning:''}]}catch(e){quick.value.error=e.message}finally{quick.value.busy=false}}
function imageChanged(upload,key){const file=upload.raw;if(!file)return;const url=URL.createObjectURL(file);if(key==='cover'){coverPreview.value=url;articleForm.coverImage=file}else{detailPreview.value=url;articleForm.detailImage=file}}
function analysisCommand(command,value=null){analysisEditor.value?.focus();document.execCommand(command,false,value);analysisForm.html=analysisEditor.value?.innerHTML||''}
function onAnalysisInput(){analysisForm.html=analysisEditor.value?.innerHTML||''}
function toggleFormat(format){if(analysisForm.format==='html'&&analysisEditor.value)analysisForm.html=analysisEditor.value.innerHTML;analysisForm.format=format}
function lettersFor(q){return letters.slice(0,Math.max(2,Math.min(8,questionOptions(q).length))).split('')}
</script>

<template><AdminLayout :title="editorTitle" :section="isChapter?'内容管理 / 外刊小说 / 章节':'内容管理 / 精读文章'" :description="editing?`${isChapter?'章节':'文章'} ID #${article.id} · 更新正文、解析、词汇与阅读题`:`新建${isChapter?'章节':'文章'}，保存后可继续添加解析、词汇与阅读题。`"><template #actions><Link class="btn secondary" :href="isChapter?`/admin/series/${series.id}/edit`:'/admin/articles'">← {{isChapter?'返回小说目录':'返回列表'}}</Link></template>
  <div class="split-panel"><div class="form-stack">
    <section class="card"><div class="card-header"><div><h2>基本信息与正文</h2><p>文章标题、内容和版权来源</p></div></div><div class="card-body"><form class="form-stack" @submit.prevent="saveArticle">
      <div class="form-grid"><div v-if="isChapter" class="form-field"><label>章节序号 <b class="required-mark">*</b></label><el-input v-model="articleForm.chapterNo" type="number" min="1" required /></div><div class="form-field"><label>英文标题 <b class="required-mark">*</b></label><el-input v-model="articleForm.title" required /></div><div class="form-field"><label>中文标题</label><el-input v-model="articleForm.translation" /></div><div class="form-field"><label>阅读级别</label><el-select v-model="articleForm.level" clearable placeholder="请选择阅读级别"><el-option v-for="level in readingLevels" :key="level.value" :value="level.value" :label="level.label" :disabled="level.disabled"/></el-select></div><div class="form-field"><label>预计阅读分钟数</label><el-input v-model="articleForm.minutes" type="number" min="1" /></div><div v-if="!isChapter" class="form-field"><label>列表显示顺序</label><el-input v-model="articleForm.sortOrder" type="number" min="0" /></div><div v-if="!isChapter" class="form-field"><label>内容标识 slug</label><el-input v-model="articleForm.slug" /></div></div>
      <div class="article-images"><div class="form-field"><label>方形封面图</label><div class="cover-upload"><div class="cover-preview square"><img v-if="coverPreview" :src="coverPreview" alt="封面预览"><span v-else>暂无封面</span></div><div class="cover-upload-controls"><el-upload :auto-upload="false" :show-file-list="false" accept="image/jpeg,image/png,image/webp" :on-change="file=>imageChanged(file,'cover')"><el-button>选择封面</el-button></el-upload><p class="form-hint">建议 1:1 方图，最大 4 MB。</p></div></div></div><div class="form-field"><label>详情横图</label><div class="cover-upload"><div class="cover-preview landscape"><img v-if="detailPreview" :src="detailPreview" alt="详情图预览"><span v-else>暂无详情图</span></div><div class="cover-upload-controls"><el-upload :auto-upload="false" :show-file-list="false" accept="image/jpeg,image/png,image/webp" :on-change="file=>imageChanged(file,'detail')"><el-button>选择详情图</el-button></el-upload><p class="form-hint">建议 16:9 横图，最大 4 MB。</p></div></div></div></div>
      <div><div class="card-header nested-header"><div><h2>文章正文</h2><p>英文和中文都按一行一句录入；中文行与英文句子顺序对应，保存时自动汇总为段落译文。</p></div></div><el-collapse v-model="expandedParagraphs" class="editor-collapse"><el-collapse-item v-for="(p,i) in articleForm.paragraphs" :key="i" :name="String(i)"><template #title><div class="collapse-title"><strong>第 {{i+1}} 段</strong><el-tag class="collapse-count" size="small" effect="plain">{{paragraphSentenceCount(p)}} 句</el-tag><span class="collapse-summary">{{paragraphPreview(p)}}</span></div></template><div class="form-grid"><div class="form-field wide"><label>英文句子（一行一句） <b class="required-mark">*</b></label><el-input :model-value="p.sentences" type="textarea" :rows="5" required @update:model-value="updateParagraphSentences(p,$event)" /><small class="form-hint">当前 {{paragraphSentenceCount(p)}} 句。</small></div><div class="form-field wide"><label>逐句中文翻译（一行一句） <b class="required-mark">*</b></label><el-input v-model="p.translation" type="textarea" :rows="5" required placeholder="每行对应上面同顺序的一句英文。保存后自动拼接为段落译文。" /><small class="form-hint" :class="{'translation-count-warning':translationLineCount(p)!==paragraphSentenceCount(p)}">当前 {{translationLineCount(p)}} 行译文 / {{paragraphSentenceCount(p)}} 句英文。行数一致即可自动逐句对应。</small></div><div class="wide collapse-actions"><el-button v-if="articleForm.paragraphs.length>1" link type="danger" native-type="button" @click="removeParagraph(i)">移除本段</el-button></div></div></el-collapse-item></el-collapse><el-button @click="addParagraph">＋ 添加段落</el-button></div>
      <div v-if="!isChapter" class="form-grid"><div class="form-field"><label>版权来源类型 <b class="required-mark">*</b></label><el-select v-model="articleForm.rightsType" placeholder="请选择"><el-option value="original" label="原创"/><el-option value="authorized" label="已获授权"/><el-option value="public_domain" label="公版作品"/><el-option value="excerpt" label="摘编 / 节选"/><el-option value="other" label="其他"/></el-select></div><div class="form-field wide"><label>版权与来源说明</label><el-input v-model="articleForm.rightsNote" type="textarea" :rows="3" /></div></div><p v-else class="form-hint">此章节可沿用小说级版权来源类型；来源说明为选填。</p>
      <div class="section-actions"><el-button type="primary" :loading="articleForm.processing" @click="saveArticle">{{articleForm.processing?'正在保存…':`保存${isChapter?'章节':'文章'}`}}</el-button><span class="helper">{{isChapter?'章节默认为草稿；可在小说目录中单独发布。':'文章默认为草稿；发布操作在文章列表进行。'}}</span></div>
    </form></div></section>
    <template v-if="editing">
      <section class="card"><div class="card-header"><div><h2>本文语法解析</h2><p>可粘贴 Markdown，前台会显示为排版后的内容。</p></div></div><div class="card-body"><form class="form-stack" @submit.prevent="saveAnalysis"><div class="form-grid"><div class="form-field"><label>内容形式</label><el-select v-model="analysisForm.type"><el-option value="richtext" label="富文本内容"/><el-option value="officialAccount" label="公众号文章链接"/></el-select></div><div v-if="analysisForm.type==='richtext'" class="form-field"><label>编辑格式</label><el-radio-group :model-value="analysisForm.format" @update:model-value="toggleFormat"><el-radio-button value="html">富文本</el-radio-button><el-radio-button value="markdown">Markdown</el-radio-button></el-radio-group></div></div><template v-if="analysisForm.type==='richtext'"><div v-if="analysisForm.format==='html'" class="form-field"><div class="toolbar"><el-button size="small" @click="analysisCommand('bold')">粗体</el-button><el-button size="small" @click="analysisCommand('italic')">斜体</el-button><el-button size="small" @click="analysisCommand('insertUnorderedList')">列表</el-button><el-button size="small" @click="analysisCommand('formatBlock','h3')">小标题</el-button></div><div ref="analysisEditor" class="rich-editor" contenteditable="true" v-html="analysisForm.html" @input="onAnalysisInput"></div></div><el-input v-else v-model="analysisForm.html" class="markdown-editor" type="textarea" :rows="14" placeholder="粘贴 Markdown 内容…"/></template><div v-else class="form-grid"><div class="form-field wide"><label>公众号文章链接</label><el-input v-model="analysisForm.url" type="url"/></div><div class="form-field"><label>文章标题</label><el-input v-model="analysisForm.title"/></div><div class="form-field"><label>摘要</label><el-input v-model="analysisForm.summary"/></div></div><div class="section-actions"><el-button type="primary" native-type="submit" :loading="analysisForm.processing">保存解析</el-button></div></form></div></section>
      <section class="card"><div class="card-header"><div><h2>重点词汇</h2><p>搜索添加到本文；单词可在单词管理中完善详解。</p></div><span class="helper">已选 {{selected.length}} 个</span></div><div class="card-body"><div class="selected-words"><span v-for="w in selected" :key="w.id" class="selected-word"><span>{{w.headword}} <small>{{w.meaning}}</small><el-tag v-if="w.status!=='published'" size="small" type="warning">草稿</el-tag></span><el-button link type="danger" @click="removeWord(w.id)">×</el-button></span></div><div class="picker-tools"><el-input v-model="search" class="picker-search" placeholder="输入英文单词或中文释义搜索"/><el-button @click="quick.open=true">＋ 新建单词</el-button></div><div class="word-picker"><p v-if="searching" class="helper">正在搜索…</p><p v-else-if="search.trim().length===0" class="helper">输入至少一个字，查看匹配结果。</p><p v-else-if="!results.length" class="helper">没有匹配的单词。</p><div v-for="w in results" :key="w.id" class="word-option"><span>{{w.headword}} <small>{{w.meaning}}</small><el-tag v-if="w.status!=='published'" size="small" type="warning">草稿</el-tag></span><el-button size="small" :disabled="selected.some(x=>x.id===Number(w.id))" @click="addWord(w)">{{selected.some(x=>x.id===Number(w.id))?'已添加':'添加'}}</el-button></div></div><el-button type="primary" :loading="wordForm.processing" @click="syncWords">保存重点词汇</el-button></div></section>
      <section class="card"><div class="card-header"><div><h2>阅读理解题</h2><p>按题目顺序展示；支持选择题和填空题。</p></div><el-button @click="addQuestion">＋ 添加题目</el-button></div><div class="card-body"><form @submit.prevent="saveQuestions"><el-collapse v-model="expandedQuestions" class="editor-collapse question-collapse"><el-collapse-item v-for="(q,i) in questionForm.questions" :key="q.uiKey" :name="q.uiKey"><template #title><div class="collapse-title"><strong>题目 {{i+1}}</strong><el-tag class="collapse-count" size="small" effect="plain">{{q.questionType}}</el-tag><el-tag class="collapse-count" size="small" :type="q.kind==='choice'?'':'success'">{{q.kind==='choice'?'选择题':'填空题'}}</el-tag><span class="collapse-summary">{{questionPreview(q)}}</span></div></template><div class="form-grid"><div class="form-field"><label>题型</label><el-select v-model="q.questionType"><el-option v-for="t in ['细节理解','主旨大意','推理判断','词义猜测','标题归纳','其他']" :key="t" :value="t" :label="t"/></el-select></div><div class="form-field"><label>作答方式</label><el-select v-model="q.kind"><el-option value="choice" label="选择题"/><el-option value="fill" label="填空题"/></el-select></div><div class="form-field wide"><label>英文题目 *</label><el-input v-model="q.prompt" type="textarea" :rows="2" required /></div><div class="form-field wide"><label>中文题目</label><el-input v-model="q.promptCn" type="textarea" :rows="2" /></div><div v-if="q.kind==='choice'" class="form-field wide"><label>选项（每行一个）</label><el-input v-model="q.options" type="textarea" :rows="4"/><p class="form-hint">填写 2–8 个选项。</p></div><div class="form-field"><label>{{q.kind==='choice'?'正确选项':'参考答案'}}</label><el-select v-if="q.kind==='choice'" v-model="q.answer"><el-option v-for="letter in lettersFor(q)" :key="letter" :value="letter" :label="letter"/></el-select><el-input v-else v-model="q.answer" /></div><div class="form-field wide"><label>答案解析</label><el-input v-model="q.explanation" type="textarea" :rows="3" /></div><div class="wide collapse-actions"><el-button link type="danger" native-type="button" @click="removeQuestion(i)">移除本题</el-button></div></div></el-collapse-item></el-collapse><div class="section-actions"><el-button type="primary" native-type="submit" :loading="questionForm.processing">保存阅读理解题</el-button></div></form></div></section>
    </template>
  </div><aside class="form-stack"><section class="card"><div class="card-header"><h2>编辑提示</h2></div><div class="card-body"><p class="helper">文章保存后默认为草稿。发布和下架操作在文章列表中进行。</p></div></section><section v-if="editing" class="card"><div class="card-header"><h2>文章信息</h2></div><div class="card-body"><div class="helper">ID：#{{article.id}}</div><div class="helper" style="margin-top:8px">最后更新：{{article.updated_at}}</div></div></section></aside></div>
  <el-dialog v-model="quick.open" title="添加单词" width="min(680px, 92vw)"><form class="form-stack" @submit.prevent="quickCreate"><p class="helper">新词先保存为草稿，可稍后补充详解。</p><div class="form-grid"><div class="form-field"><label>单词 *</label><el-input v-model="quick.headword" required /></div><div class="form-field"><label>音标</label><el-input v-model="quick.ipa" /></div></div><div class="quick-senses"><div class="quick-senses-head"><strong>词性与简明释义</strong><el-button size="small" @click="addQuickSense">＋ 添加释义</el-button></div><div v-for="(sense,index) in quick.senses" :key="index" class="quick-sense-row"><el-input v-model="sense.partOfSpeech" placeholder="词性，如 n. / v."/><el-input v-model="sense.meaning" placeholder="简明释义" required/><el-button v-if="quick.senses.length>1" link type="danger" @click="removeQuickSense(index)">移除</el-button></div></div><el-alert v-if="quick.error" :title="quick.error" type="error" :closable="false"/><div class="section-actions"><el-button @click="quick.open=false">取消</el-button><el-button type="primary" native-type="submit" :loading="quick.busy">创建并添加到本文</el-button></div></form></el-dialog>
